import{_ as a,o,c as r,ae as l}from"./chunks/framework.YL6nI5ZP.js";const h=JSON.parse('{"title":"Glosario","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/08-glosario.md","filePath":"es/reference/08-glosario.md"}'),d={name:"es/reference/08-glosario.md"};function i(t,e,n,s,c,u){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="glosario" tabindex="-1">Glosario <a class="header-anchor" href="#glosario" aria-label="Permalink to &quot;Glosario&quot;">​</a></h1><p>Lista alfabética de los términos del proyecto y sus significados. Fusiona el glosario del manual de ingeniería con el glosario de dominio de <code>CONTEXT.md</code>; cuando el glosario de dominio define un término en español, ese término se usa como primario, con el inglés entre paréntesis.</p><h2 id="_1d-2d" tabindex="-1">1D / 2D <a class="header-anchor" href="#_1d-2d" aria-label="Permalink to &quot;1D / 2D&quot;">​</a></h2><p>Modelo de tuberías/red vs. modelo de malla de tránsito superficial por el terreno.</p><h2 id="cd-coupling" tabindex="-1">CD / coupling <a class="header-anchor" href="#cd-coupling" aria-label="Permalink to &quot;CD / coupling&quot;">​</a></h2><p>Coeficiente de flujo / coeficiente de intercambio 1D↔2D (por defecto 0.65).</p><h2 id="cdt" tabindex="-1">CDT <a class="header-anchor" href="#cdt" aria-label="Permalink to &quot;CDT&quot;">​</a></h2><p>Triangulación de Delaunay restringida (Constrained Delaunay Triangulation).</p><h2 id="cfl" tabindex="-1">CFL <a class="header-anchor" href="#cfl" aria-label="Permalink to &quot;CFL&quot;">​</a></h2><p>Condición de estabilidad de Courant–Friedrichs–Lewy.</p><h2 id="cplf-cpls" tabindex="-1">cplF / cplS <a class="header-anchor" href="#cplf-cpls" aria-label="Permalink to &quot;cplF / cplS&quot;">​</a></h2><p>Búferes de acople de flujo/estado entre el motor 1D WASM y el marchante 2D GPU.</p><h2 id="engineclient" tabindex="-1">EngineClient <a class="header-anchor" href="#engineclient" aria-label="Permalink to &quot;EngineClient&quot;">​</a></h2><p>Seam del frontend entre la UI y el motor, con dos implementaciones conmutables: local (WASM en el navegador) y remota (vía API). <em>Evitar</em>: módulo del motor, wrapper del motor.</p><h2 id="pool-de-workers-del-motor-engine-worker-pool" tabindex="-1">Pool de workers del motor (Engine worker pool) <a class="header-anchor" href="#pool-de-workers-del-motor-engine-worker-pool" aria-label="Permalink to &quot;Pool de workers del motor (Engine worker pool)&quot;">​</a></h2><p>Conjunto de procesos nativos en el servidor que ejecutan corridas, uno por núcleo, tomando trabajo de una cola. <em>Evitar</em>: hilo, thread (salvo OpenMP dentro de un worker).</p><h2 id="feature-state" tabindex="-1">feature-state <a class="header-anchor" href="#feature-state" aria-label="Permalink to &quot;feature-state&quot;">​</a></h2><p>Estado mutable de estilo por feature de Mapbox GL JS.</p><h2 id="malla-indexada-indexed-mesh" tabindex="-1">Malla indexada (Indexed mesh) <a class="header-anchor" href="#malla-indexada-indexed-mesh" aria-label="Permalink to &quot;Malla indexada (Indexed mesh)&quot;">​</a></h2><p><code>Net.mesh2DIndexed</code>: la salida canónica de malla del motor Triangle.</p><h2 id="inp" tabindex="-1">INP <a class="header-anchor" href="#inp" aria-label="Permalink to &quot;INP&quot;">​</a></h2><p>Archivo de texto de entrada de SWMM (<code>.inp</code>); la serialización del modelo que consume el motor.</p><h2 id="modo-local-modo-api-local-mode-api-mode" tabindex="-1">Modo local / Modo API (Local mode / API mode) <a class="header-anchor" href="#modo-local-modo-api-local-mode-api-mode" aria-label="Permalink to &quot;Modo local / Modo API (Local mode / API mode)&quot;">​</a></h2><p>Las dos vías de ejecución del EngineClient: motor WASM en el navegador (sin conexión) vs motor en el servidor vía API (default).</p><h2 id="lts" tabindex="-1">LTS <a class="header-anchor" href="#lts" aria-label="Permalink to &quot;LTS&quot;">​</a></h2><p>Local Time Stepping — el esquema de subpasos en niveles del solver 2D.</p><h2 id="m0–m5" tabindex="-1">M0–M5 <a class="header-anchor" href="#m0–m5" aria-label="Permalink to &quot;M0–M5&quot;">​</a></h2><p>Fases de hitos de WebGPU en <code>WEBGPU_PLAN.md</code>.</p><h2 id="memfs" tabindex="-1">MEMFS <a class="header-anchor" href="#memfs" aria-label="Permalink to &quot;MEMFS&quot;">​</a></h2><p>Sistema de archivos virtual en memoria de Emscripten (<code>.inp</code>/<code>.rpt</code>/<code>.out</code> viven ahí).</p><h2 id="openswmm" tabindex="-1">OpenSWMM <a class="header-anchor" href="#openswmm" aria-label="Permalink to &quot;OpenSWMM&quot;">​</a></h2><p>La reimplementación en C++20 usada aquí (HydroCouple); licencia MIT.</p><h2 id="pslg" tabindex="-1">PSLG <a class="header-anchor" href="#pslg" aria-label="Permalink to &quot;PSLG&quot;">​</a></h2><p>Grafo planar de líneas rectas (Planar Straight-Line Graph) — la entrada de triangulación restringida para Triangle.</p><h2 id="pslc" tabindex="-1">PSLC <a class="header-anchor" href="#pslc" aria-label="Permalink to &quot;PSLC&quot;">​</a></h2><p>Grafo planar de <strong>celdas</strong> de líneas rectas (Planar Straight-Line <strong>Cell</strong> graph) — el término del módulo mesh2dPslg.</p><h2 id="rpt-out" tabindex="-1">RPT / OUT <a class="header-anchor" href="#rpt-out" aria-label="Permalink to &quot;RPT / OUT&quot;">​</a></h2><p>Reporte de texto del motor / archivos binarios de resultados.</p><h2 id="corrida-run" tabindex="-1">Corrida (Run) <a class="header-anchor" href="#corrida-run" aria-label="Permalink to &quot;Corrida (Run)&quot;">​</a></h2><p>Una ejecución completa de un modelo de simulación (1D+2D) con ciclo de vida: encolada → corriendo → terminada (o fallida). Se identifica por un ID y es lo que el usuario dispara con Run. <em>Evitar</em>: job, run, simulación (la simulación es el fenómeno modelado; la corrida es la ejecución).</p><h2 id="progreso-de-corrida-run-progress" tabindex="-1">Progreso de corrida (Run progress) <a class="header-anchor" href="#progreso-de-corrida-run-progress" aria-label="Permalink to &quot;Progreso de corrida (Run progress)&quot;">​</a></h2><p>Estado en vivo de una corrida: sim-time alcanzado, fracción del total, fase. Consultable por ID; es lo que pinta la UI de Run Status.</p><h2 id="resultados-de-corrida-run-results" tabindex="-1">Resultados de corrida (Run results) <a class="header-anchor" href="#resultados-de-corrida-run-results" aria-label="Permalink to &quot;Resultados de corrida (Run results)&quot;">​</a></h2><p>Producto terminado de una corrida: tablas JSON (series 1D por nodo/enlace/subcuenca y frames 2D capturados en vivo) más los archivos binarios <code>.out</code> y <code>.rpt</code> para export.</p><h2 id="swmm" tabindex="-1">SWMM <a class="header-anchor" href="#swmm" aria-label="Permalink to &quot;SWMM&quot;">​</a></h2><p>EPA Storm Water Management Model; la referencia de hidrología/hidráulica.</p><h2 id="estado-del-sistema-system-status" tabindex="-1">Estado del sistema (System status) <a class="header-anchor" href="#estado-del-sistema-system-status" aria-label="Permalink to &quot;Estado del sistema (System status)&quot;">​</a></h2><p>Endpoint agregado de salud: versión de la app, estado del pool de workers, corridas activas. Consultable para scripts, CI y depuración. <em>Evitar</em>: health endpoint, status de corrida (eso es el progreso de una corrida concreta).</p><h2 id="triangle" tabindex="-1">Triangle <a class="header-anchor" href="#triangle" aria-label="Permalink to &quot;Triangle&quot;">​</a></h2><p>El triangulador de Delaunay de Shewchuk; aquí compilado a WASM (<code>triangle-wasm</code>).</p><h2 id="wasm-emscripten" tabindex="-1">WASM / Emscripten <a class="header-anchor" href="#wasm-emscripten" aria-label="Permalink to &quot;WASM / Emscripten&quot;">​</a></h2><p>WebAssembly + el toolchain de LLVM que compila C++ a WASM.</p>',52)])])}const p=a(d,[["render",i]]);export{h as __pageData,p as default};
